{"judgments": [
  {"clause_id": "c019",
   "issues": [
     {"issue": "The stated effective date (August 1, 1997) precedes the date in the preamble, which says the Agreement is made on a day in 1999, so the instrument gives two irreconcilable starting points. Nothing says which controls or what the retroactive period covers.", "type": 2, "prob": 0.26}
   ]},
  {"clause_id": "c020",
   "issues": [
     {"issue": "\"Filing of Securities by Issue (FOSBI) arrangement\" is used without definition and the clause does not say who elects between segregated holding and fungible bulk. The choice is left wholly at large.", "type": 1, "prob": 0.16}
   ]},
